'use client'
import { useId, useLayoutEffect, useRef, useState, type KeyboardEvent } from 'react'
import { Code } from '@/react/components/site/Code'
import { CopyButton } from '@/react/components/site/CopyButton'
import { codeTabsExample, type CodeTab } from '@/lib/code'
import { cn } from '@/react/lib/cn'

// The site's tabs of code (sections/Connect CodeTabs, Code, CopyButton): a #262626 panel with an 8px corner; a 56px
// head with the tabs (14/20 Medium in the muted gray, White when chosen, the soft gray under the pointer; a 2px White
// line under the chosen one that slides to the next) and the copy button for the shown tab, over a hairline; under it
// the code, 16px in (24 from 768), scrolling across and fading at its edges. Arrows, Home and End move between tabs.
export interface CodeBlockProps {
  /** The tabs: { id, label, code, language }. One tab still shows its label. */
  tabs?: CodeTab[]
  /** The tab list's accessible name. */
  label?: string
  copy?: { label: string; copiedLabel: string; name: string }
  onCopy?: (text: string) => void
  className?: string
}

export function CodeBlock({ tabs = codeTabsExample, label = 'Code', copy = { label: 'Copy', copiedLabel: 'Copied', name: 'Copy code' }, onCopy, className }: CodeBlockProps) {
  const [active, setActive] = useState(0)
  const [line, setLine] = useState<{ x: number; w: number } | null>(null)
  const id = useId()
  const listRef = useRef<HTMLDivElement>(null)
  const buttons = useRef<(HTMLButtonElement | null)[]>([])

  // The line moves by transform only: a 100px bar placed and scaled to the chosen tab's label.
  useLayoutEffect(() => {
    const list = listRef.current
    if (!list) return
    const measure = () => {
      const tab = buttons.current[active]
      if (!tab || !tab.offsetWidth) return
      const pad = parseFloat(getComputedStyle(tab).paddingLeft)
      setLine({ x: tab.offsetLeft + pad, w: tab.offsetWidth - 2 * pad })
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(list)
    return () => observer.disconnect()
  }, [active])

  const select = (index: number) => {
    setActive(index)
    const tab = buttons.current[index]
    const list = listRef.current
    if (!tab || !list) return
    const t = tab.getBoundingClientRect()
    const l = list.getBoundingClientRect()
    if (t.left < l.left) list.scrollLeft += t.left - l.left
    else if (t.right > l.right) list.scrollLeft += t.right - l.right
  }

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const last = tabs.length - 1
    const next = e.key === 'ArrowRight' ? (active === last ? 0 : active + 1) : e.key === 'ArrowLeft' ? (active === 0 ? last : active - 1) : e.key === 'Home' ? 0 : e.key === 'End' ? last : -1
    if (next < 0) return
    e.preventDefault()
    select(next)
    buttons.current[next]?.focus()
  }

  if (!tabs.length) return null
  const shown = tabs[active] ?? tabs[0]

  return (
    <div data-ds="code-block" className={cn('min-w-0 rounded-control bg-surface-raised text-fg', className)}>
      <div className="relative flex h-control-lg items-center justify-between gap-2 px-1 after:absolute after:inset-x-0 after:bottom-0 after:h-px after:bg-edge-surface md:px-2">
        <div ref={listRef} role="tablist" aria-label={label} onKeyDown={onKeyDown} className="fade-x relative isolate flex h-full min-w-0 overflow-x-auto [scrollbar-width:none]">
          {line ? <span aria-hidden="true" className="pointer-events-none absolute bottom-0 left-0 z-0 h-0.5 w-25 origin-left bg-fg transition-transform duration-160 ease-loop motion-reduce:transition-none" style={{ transform: `translateX(${line.x}px) scaleX(${line.w / 100})` }} /> : null}
          {tabs.map((tab, i) => (
            <button
              key={tab.id}
              ref={(node) => { buttons.current[i] = node }}
              type="button"
              role="tab"
              id={`${id}-tab-${tab.id}`}
              aria-selected={i === active}
              aria-controls={`${id}-panel-${tab.id}`}
              tabIndex={i === active ? 0 : -1}
              onClick={() => select(i)}
              className="relative z-1 h-full flex-none cursor-pointer rounded-ds-sm px-3 type-ui-strong text-fg-muted transition-[color] duration-160 ease-out outline-offset-[calc(-1*var(--ds-border-focus))] hover:not-aria-selected:text-fg-soft active:text-fg aria-selected:text-fg md:px-4"
            >
              {tab.label}
            </button>
          ))}
        </div>
        <CopyButton key={shown.id} text={shown.code} label={copy.label} copiedLabel={copy.copiedLabel} name={copy.name} selectId={`${id}-panel-${shown.id}`} onCopy={onCopy} />
      </div>
      <div className="grid grid-cols-[minmax(0,1fr)]">
        {tabs.map((tab, i) => (
          <div
            key={tab.id}
            role="tabpanel"
            id={`${id}-panel-${tab.id}`}
            aria-labelledby={`${id}-tab-${tab.id}`}
            tabIndex={i === active ? 0 : -1}
            inert={i !== active}
            className={cn('fade-x min-w-0 overflow-x-auto rounded-b-control p-4 outline-offset-[calc(-1*var(--ds-border-focus))] [grid-area:1/1] [scrollbar-color:var(--ds-color-edge-strong)_transparent] [scrollbar-width:thin] md:p-6', i === active ? 'visible' : 'invisible')}
          >
            <Code source={tab.code} language={tab.language} />
          </div>
        ))}
      </div>
    </div>
  )
}

export default CodeBlock

import { codeRuns } from '@/lib/code'
import { cn } from '@/react/lib/cn'

// The site's code (sections/Connect Code): mono 14/20 in White, as wide as its longest line, with comments,
// punctuation and string quotes in the muted gray. Put it in something that scrolls across.
export interface CodeProps {
  source: string
  /** shell, ts, python or json (json keeps `#` as text). */
  language?: string
  className?: string
}

export function Code({ source, language = 'shell', className }: CodeProps) {
  return (
    <pre data-ds="code" className={cn('m-0 w-max type-code text-fg [tab-size:2]', className)}>
      <code>{codeRuns(source, language).map((r, i) => (r.dim ? <span key={i} className="text-fg-muted">{r.text}</span> : r.text))}</code>
    </pre>
  )
}

export default Code

'use client'
import { useEffect, useRef, useState } from 'react'
import { copyText } from '@/lib/code'
import { cn } from '@/react/lib/cn'

// The site's copy button (sections/Connect CopyButton): a quiet 40px button with a 4px corner, its label in the soft
// gray (White under the pointer); a press puts `text` on the clipboard and the label crosses over to "Copied" (up and
// out, up and in, 160ms) for 2s. If the clipboard is refused, the text in `selectId` is selected instead.
export interface CopyButtonProps {
  text: string
  label?: string
  copiedLabel?: string
  /** Its accessible name. */
  name?: string
  /** The element whose text is selected when copying is refused. */
  selectId?: string
  onCopy?: (text: string) => void
  className?: string
}

export const COPY_BUTTON =
  'ds-copy relative inline-flex h-control-md min-w-20 flex-none cursor-pointer items-center justify-center rounded-ds-sm bg-action-secondary px-4 type-ui-strong whitespace-nowrap text-fg-soft shadow-[inset_0_0_0_var(--ds-border-hairline)_var(--ds-color-action-secondary-edge)] transition-[background-color,color] duration-160 ease-out select-none before:absolute before:-inset-y-2 before:inset-x-0 hover:bg-action-secondary-hover hover:text-fg data-copied:text-fg'

export function CopyButton({ text, label = 'Copy', copiedLabel = 'Copied', name = 'Copy code', selectId, onCopy, className }: CopyButtonProps) {
  const [copied, setCopied] = useState(false)
  const timer = useRef<number | undefined>(undefined)
  useEffect(() => () => window.clearTimeout(timer.current), [])

  const copy = async () => {
    const ok = await copyText(text)
    if (!ok) {
      const target = selectId ? document.getElementById(selectId) : null
      if (target) window.getSelection()?.selectAllChildren(target)
      return
    }
    setCopied(true)
    onCopy?.(text)
    window.clearTimeout(timer.current)
    timer.current = window.setTimeout(() => setCopied(false), 2000)
  }

  return (
    <span data-ds="copy-button" className="contents">
      <style href="ds-copy-button" precedence="ds">{css}</style>
      <button type="button" aria-label={name} data-copied={copied || undefined} className={cn(COPY_BUTTON, className)} onClick={copy}>
        <span aria-hidden="true" className="grid justify-items-center">
          <span className="ds-copy-idle [grid-area:1/1]">{label}</span>
          <span className="ds-copy-done [grid-area:1/1]">{copiedLabel}</span>
        </span>
      </button>
      <span role="status" className="sr-only">{copied ? copiedLabel : ''}</span>
    </span>
  )
}

export default CopyButton

const css = `
.ds-copy-idle, .ds-copy-done { transition: opacity var(--ds-duration-micro) var(--ds-easing-out), transform var(--ds-duration-micro) var(--ds-easing-out); }
.ds-copy-done { opacity: 0; transform: translateY(var(--ds-space-xs)); }
.ds-copy[data-copied] .ds-copy-idle { opacity: 0; transform: translateY(calc(-1 * var(--ds-space-xs))); }
.ds-copy[data-copied] .ds-copy-done { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .ds-copy-done, .ds-copy[data-copied] .ds-copy-idle { transform: none; }
}
`

// The site's code display (sections/Connect Code, CopyButton): source split into runs, with comments, punctuation and
// string quotes in the muted gray and everything else White; and a copy that falls back to a hidden textarea. Both
// flavors read it.
export interface CodeRun { text: string; dim?: boolean }

const TOKEN = /(#.*$)|("(?:[^"\\]|\\.)*")|(https?:\/\/[^\s"']+)|([{}[\]():,=\\.'])/gm

/** The runs of `source`; JSON keeps `#` as text. */
export function codeRuns(source: string, language = 'shell'): CodeRun[] {
	const out: CodeRun[] = []
	let last = 0
	for (const match of source.matchAll(TOKEN)) {
		const [text, comment, string, url, mark] = match
		const at = match.index ?? 0
		if (comment && language === 'json') continue
		if (at > last) out.push({ text: source.slice(last, at) })
		if (comment || mark) out.push({ text, dim: true })
		else if (url) out.push({ text })
		else if (string) out.push({ text: '"', dim: true }, { text: string.slice(1, -1) }, { text: '"', dim: true })
		last = at + text.length
	}
	if (last < source.length) out.push({ text: source.slice(last) })
	return out
}

/** Puts `text` on the clipboard; true when it worked. */
export async function copyText(text: string): Promise<boolean> {
	try {
		await navigator.clipboard.writeText(text)
		return true
	} catch {}
	const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null
	const area = document.createElement('textarea')
	area.value = text
	area.setAttribute('readonly', '')
	area.style.cssText = 'position:fixed;opacity:0;pointer-events:none'
	document.body.append(area)
	area.focus({ preventScroll: true })
	area.select()
	let ok = false
	try {
		ok = document.execCommand('copy')
	} catch {}
	area.remove()
	previous?.focus({ preventScroll: true })
	return ok
}

export interface CodeTab { id: string; label: string; code: string; language?: string }

export const codeTabsExample: CodeTab[] = [
	{ id: 'curl', label: 'cURL', language: 'shell', code: '# Search the ads of a brand\ncurl "https://api.acme.com/v1/search" \\\n  -H "Authorization: Bearer $ACME_KEY" \\\n  -d \'{"query": "skincare launches", "limit": 20}\'' },
	{ id: 'ts', label: 'TypeScript', language: 'ts', code: 'const res = await fetch("https://api.acme.com/v1/search", {\n  method: "POST",\n  headers: { Authorization: `Bearer ${key}` },\n  body: JSON.stringify({ query: "skincare launches", limit: 20 }),\n})' },
	{ id: 'py', label: 'Python', language: 'python', code: 'import requests\n\nres = requests.post(\n  "https://api.acme.com/v1/search",\n  headers={"Authorization": f"Bearer {key}"},\n  json={"query": "skincare launches", "limit": 20},\n)' },
]

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

